(()=>{
 const people={mina:{name:'Mina',role:'Business intelligence',greeting:"Hi, I’m Mina. Tell me what you’d like to build or improve, and we’ll work through it together."},vela:{name:'Vela',role:'Reasoning & strategy',greeting:"Hey, I’m Vela. I can help you explore Terqyn and find the right next step. Tell me what you’re working through. My staff workspace stays behind secure sign-in."},aethon:{name:'Atlas',role:'Analysis & synthesis',greeting:'I’m Atlas. Tell me what you’d like to understand or analyze, and we’ll work through it together.'}};
 people.vera={name:'Vera',role:'Intelligence reserved · Not active',reserved:true,greeting:'Vera’s place in Terqyn is reserved. Her specialty and secure connection are being prepared. Live conversations are not active yet.'};
 people.caelis={name:'Caelis',role:'The Research Sentinel · Not active',reserved:true,greeting:'I’m Caelis, Terqyn’s Research Sentinel. My role is to investigate public information, compare sources, check dates, and distinguish evidence from inference. My style is calm, exact, and curious. Live research and conversations are not active yet.'};
 let aethonReady=false;
 const turns=Object.fromEntries(Object.keys(people).map(id=>[id,[]]));let selected=null;let opener;const busy=new Set();
 const dock=document.createElement('div');dock.className='hq-oracles';dock.setAttribute('aria-label','Terqyn intelligences');dock.innerHTML=Object.entries(people).map(([id,p])=>`<button class="hq-orb" data-persona="${id}" aria-label="${p.reserved?'View '+p.name+' — coming soon':'Talk to '+p.name}" aria-expanded="false" aria-controls="hq-oracle-chat">${p.name}</button>`).join('');
 const panel=document.createElement('section');panel.id='hq-oracle-chat';panel.className='hq-chat';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-labelledby','hq-oracle-title');panel.innerHTML='<header><div><h2 id="hq-oracle-title"></h2><small></small></div><button type="button" aria-label="Close Oracle">×</button></header><div class="hq-chat-log" role="log" aria-live="polite" aria-relevant="additions"></div><form><textarea aria-label="Your message" rows="2" maxlength="2000" placeholder="Type your message…" required></textarea><button type="submit">Send</button></form><footer>Complimentary AI guidance · Fair-use limits apply · Paid services are separate.<br>Don’t share confidential information. This chat stays separate from staff memory.<br><a href="https://www.terqynsystems.com/#portal/dashboard">Secure staff workspace ↗</a> · <button type="button" data-clear style="background:none;border:0;text-decoration:underline;font:inherit;cursor:pointer">Clear this chat</button></footer>';
 document.body.append(dock,panel);const log=panel.querySelector('[role=log]'),input=panel.querySelector('textarea'),send=panel.querySelector('[type=submit]');
 fetch('/api/oracle').then(r=>r.ok?r.json():{}).then(p=>{if(p.aethon){aethonReady=true;people.aethon.role='Analysis & synthesis';people.aethon.greeting='I’m Atlas. What would you like to analyze? This HQ interface supports text; file, image and video uploads are not available here yet.';if(selected==='aethon'){panel.querySelector('small').textContent=people.aethon.role;draw();}}}).catch(()=>{});
 function append(role,text){const p=document.createElement('p');p.dataset.role=role;p.textContent=text;log.append(p);log.scrollTop=log.scrollHeight;}
 function draw(){log.replaceChildren();append('assistant',people[selected].greeting);for(const m of turns[selected])append(m.role,m.content);send.disabled=busy.has(selected)||people[selected].reserved||(selected==='aethon'&&!aethonReady);input.disabled=people[selected].reserved||(selected==='aethon'&&!aethonReady);input.placeholder=people[selected].reserved?'This intelligence is being prepared.':'Type your message…';if(busy.has(selected))append('assistant','Thinking…');}
 function close(){panel.hidden=true;dock.querySelectorAll('button').forEach(b=>b.setAttribute('aria-expanded','false'));opener?.focus();}
 dock.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(!panel.hidden&&selected===b.dataset.persona){close();return;}selected=b.dataset.persona;opener=b;panel.querySelector('h2').textContent=people[selected].name;panel.querySelector('small').textContent=people[selected].role;panel.hidden=false;dock.querySelectorAll('button').forEach(x=>x.setAttribute('aria-expanded',String(x===b)));draw();if(!input.disabled)input.focus();});
 panel.querySelector('header button').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)close();});
 panel.querySelector('[data-clear]').onclick=()=>{if(!busy.has(selected)){turns[selected]=[];draw();}};
 function history(items){let result=items.filter(m=>!m.error).slice(-15);while(result.length>1&&(result[0].role!=='user'||new TextEncoder().encode(JSON.stringify(result)).length>11000))result.shift();return result;}
 panel.querySelector('form').onsubmit=async e=>{e.preventDefault();const id=selected,text=input.value.trim();if(!text||busy.has(id)||people[id].reserved||(id==='aethon'&&!aethonReady))return;turns[id].push({role:'user',content:text});input.value='';busy.add(id);draw();try{let reply;{const r=await fetch('/api/oracle',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({persona:id,messages:history(turns[id])})});const p=await r.json();if(!r.ok)throw Error(p.error||'Connection unavailable.');reply=p.text;}turns[id].push({role:'assistant',content:reply});}catch(err){turns[id].pop();turns[id].push({role:'assistant',content:err.message||'Please try again shortly.',error:true});}finally{busy.delete(id);if(selected===id){draw();input.focus();}}};
})();

import { profiles as renamedProfiles } from '../lib/character-routing.mjs';
const approvedNames={muse:'Nova',aegis:'Reid',vera:'Luca',aethon:'Atlas',vector:'Axel',caelis:'Jett'};
for(const [id,name] of Object.entries(approvedNames))if(renamedProfiles[id])renamedProfiles[id].name=name;
import handler from '../lib/oracle-handler.mjs';
import { nexusOrigin } from '../lib/nexus-origin.mjs';
import { reservedIntelligences } from '../lib/agent-slots.mjs';
import { characterRouting } from '../lib/character-routing.mjs';
import { withQuotaFeedback } from '../lib/chat-quota-feedback.mjs';
const routed=withQuotaFeedback(nexusOrigin(characterRouting(reservedIntelligences(handler))));
const origins=new Set(['https://terqyn.com','https://www.terqyn.com','https://terqyn.nexus','https://www.terqyn.nexus','https://terqyn.tech','https://www.terqyn.tech']);
export default async function(req,res){
 const renamedIds={nova:'muse',reid:'aegis',luca:'vera',atlas:'aethon',axel:'vector',jett:'caelis'};
 if(req.body&&renamedIds[req.body.persona])req.body={...req.body,persona:renamedIds[req.body.persona]};
 const origin=req.headers.origin;
 if(origin&&origins.has(origin)){
  res.setHeader('Access-Control-Allow-Origin',origin);res.setHeader('Vary','Origin');
  res.setHeader('Access-Control-Allow-Methods','GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers','Content-Type');
  if(req.method==='OPTIONS')return res.status(204).end();
 }
 if(req.method==='OPTIONS')return res.status(403).end();
 if(origin&&origins.has(origin)){
  const setHeader=res.setHeader;req.headers.origin='https://terqyn.com';
  res.setHeader=function(name,value){return setHeader.call(this,name,name.toLowerCase()==='access-control-allow-origin'?origin:value)};
  try{return await routed(req,res)}finally{req.headers.origin=origin;res.setHeader=setHeader}
 }
 return routed(req,res);
}

nexus.data:
(()=>{
 const endpoint='https://terqyn.com/api/oracle';
 const names={mina:'Mina',vela:'Vela',soryn:'Soryn',aethon:'Atlas',ryx:'Ryx',prime:'Nexus Prime',vera:'Luca',caelis:'Jett',aegis:'Reid',vector:'Axel',muse:'Nova'};
 const chats=Object.fromEntries(Object.keys(names).map(k=>[k,[]]));let drafts={};try{const saved=JSON.parse(sessionStorage.getItem('nexus-conversations-v1')||'{}');for(const id of Object.keys(names))if(Array.isArray(saved.chats?.[id]))chats[id]=saved.chats[id].filter(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string').slice(-30);drafts=saved.drafts||{}}catch{};function save(){try{sessionStorage.setItem('nexus-conversations-v1',JSON.stringify({chats,drafts}))}catch{}}
 let selected='prime',busy=false;
 const panel=document.createElement('section');panel.className='panel';panel.id='public-conversation';panel.setAttribute('aria-labelledby','conversation-title');
 panel.innerHTML=`<div class="stage-tag">01 / PLAN WITH YOUR AI</div><h3 class="stage-title">Start with the idea.</h3><p class="stage-intro">Not sure what to build yet? Talk it through here. Explore possibilities, ask questions, and work out the scope before preparing your build order.</p><div class="brief-checklist"><span>Explore ideas</span><span>Clarify the goal</span><span>Shape the plan</span></div><p id="conversation-title" class="team-line">Your planning team</p><div id="conversation-log" role="log" aria-live="polite"></div><form><label class="field" for="conversation-message">WHAT ARE YOU THINKING ABOUT?</label><p id="planning-guidance" class="input-guidance">Tell us the problem, who it affects, and what you want to achieve. You do not need a technical specification to start.</p><textarea id="conversation-message" maxlength="2000" rows="5" aria-describedby="planning-guidance" placeholder="I want to [goal], but I need help figuring out [question or challenge]. My audience is [who], and I currently handle this by [current process]…" required></textarea><div class="prompt-actions"><button class="primary" type="submit">Plan With My AI ↗</button><button class="secondary" type="button" id="clear-conversation">Clear chat</button><button class="secondary" type="button" id="use-plan">Use This Conversation in My Build Brief ↓</button></div></form><p class="micro">Complimentary planning guidance · No sign-in needed · Fair-use limits apply.<br>This conversation helps define your idea. Build orders are prepared in step 02 below.</p>`;
 document.querySelector('#workspace .workgrid').before(panel);
 const style=document.createElement('style');style.textContent='#public-conversation{margin-bottom:24px}#conversation-log{max-height:430px;overflow:auto;overflow-wrap:anywhere}#conversation-log p{padding:14px;border-radius:10px;background:#0a1727;white-space:pre-wrap}#conversation-log p[data-role=user]{background:#203a4c}#public-conversation textarea{height:95px;margin-bottom:12px}#public-conversation button:disabled{opacity:.5;cursor:wait}';document.head.append(style);
 const log=panel.querySelector('[role=log]'),input=panel.querySelector('textarea'),send=panel.querySelector('[type=submit]');
 function line(role,text){const p=document.createElement('p');p.dataset.role=role;p.textContent=text;log.append(p);log.scrollTop=log.scrollHeight;}
 function draw(){if(typeof renderActiveTeam!=='function')panel.querySelector('#conversation-title').textContent=typeof selection==='function'&&!selection().length?'Choose your planning agents in the orbit above.':'Planning with '+(typeof selectedProfile==='function'?selectedProfile().name:names[selected]);log.replaceChildren();line('assistant',typeof selection==='function'&&!selection().length?'Choose one or more agents above to start planning. Describe your idea below, and your draft will stay here while you choose.':'Let’s shape your idea. What would you like to create or improve, who is it for, and what would a successful result look like?');for(const m of chats[selected])line(m.role,m.content);send.disabled=busy||(typeof selection==='function'&&!selection().length);input.disabled=busy;if(typeof renderActiveTeam==='function')renderActiveTeam();}
 function history(items){let result=items.filter(m=>!m.error).slice(-15);while(result.length>1&&(result[0].role!=='user'||new TextEncoder().encode(JSON.stringify(result)).length>11000))result.shift();return result;}
 function specialistHistory(id,items){const messages=history(items);if(typeof selection==='function'&&selection().length>1&&messages.length)messages[0]={...messages[0],content:'[Coordinate guidance for this selected Terqyn team: '+selection().map(a=>a.name+' ('+a.type+')').join(', ')+'. Do not claim separate models or tools were executed.]\n'+messages[0].content};const p=window.TERQYN_AGENTS?.find(a=>a.id===id);if(p&&messages.length)messages[0]={...messages[0],content:'[Terqyn profile: '+p.name+'. Mastery: '+p.skills.join(', ')+'. Personality: '+p.personality+'. Approach: '+p.task+' Public guidance only. Do not claim tool execution, live searches or external actions.]\n'+messages[0].content};return messages;}
 window.addEventListener('nexus-selection-change',e=>{const currentDraft=input.value;drafts[selected]=currentDraft;selected=e.detail.persona;input.value=currentDraft||drafts[selected]||'';drafts[selected]=input.value;save();draw();send.disabled=busy||!e.detail.ids.length;});
 function isIdentityOnlyReply(message) {
  const content = message.content.trim().replace(/\s+/g, ' ');
  return message.role === 'assistant' &&
   /^(?:hello!\s*)?I am Nexus Prime, your coordinator for mission planning and synthesis\.(?: I operate through TERQYN protected intelligence\.)?$/i.test(content);
 }
 panel.querySelector('#use-plan').onclick=()=>{const brief=document.getElementById('request'),messages=chats[selected].filter(m=>!m.error&&!isIdentityOnlyReply(m)).slice(-6),content=messages.length?messages.map(m=>(m.role==='user'?'My requirements: ':'Planning guidance: ')+m.content).join('\n\n'):input.value.trim();if(!content){input.focus();return}brief.value=[brief.value.trim(),'Planning conversation:\n'+content].filter(Boolean).join('\n\n');brief.dispatchEvent(new Event('input',{bubbles:true}));brief.scrollIntoView({behavior:'smooth',block:'center'});brief.focus({preventScroll:true});};
 panel.querySelector('#clear-conversation').onclick=()=>{if(!busy){chats[selected]=[];save();draw();}};
 panel.querySelector('form').onsubmit=async e=>{e.preventDefault();const text=input.value.trim(),id=selected;if(!text||busy||(typeof selection==='function'&&!selection().length))return;chats[id].push({role:'user',content:text});input.value='';drafts[id]='';save();busy=true;draw();line('assistant','Thinking…');try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({persona:id,messages:specialistHistory(id,chats[id])})});const p=await r.json();if(!r.ok)throw Error(p.error||'Please try again later.');const checked=window.TerqynAcceptance.review(text,p.text);chats[id].push({role:'assistant',content:checked.text,acceptance:checked.status});}catch(err){chats[id].pop();drafts[id]=text;if(selected===id)input.value=text;chats[id].push({role:'assistant',content:err.message||'Please try again later.',error:true});}finally{busy=false;save();draw();if(selected===id)input.focus();}};
 input.addEventListener('input',()=>{drafts[selected]=input.value;save()});input.value=drafts[selected]||'';draw();
})();
